{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_icon_stack",
        "internal_comms_header",
        "hero_image",
        "email1_card",
        "email2_card",
        "email3_card",
        "quick_actions_header",
        "quick_actions_stack"
      ]
    },
    "title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "main_title",
        "company_icon"
      ]
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "Solaris Tech: Resiliency and Strategy",
        "variant": "h1"
      },
      "children": []
    },
    "company_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "internal_comms_header": {
      "type": "Text",
      "props": {
        "text": "Internal Communications: Q4 2023",
        "variant": "h2"
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Austin_Texas_Skyline_2017.jpg/1200px-Austin_Texas_Skyline_2017.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "email1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email1_content_stack"
      ]
    },
    "email1_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email1_title",
        "email1_date",
        "email1_subject",
        "email1_body_paragraph1",
        "email1_signature"
      ]
    },
    "email1_title": {
      "type": "Text",
      "props": {
        "text": "Acknowledging Q3 Challenges",
        "variant": "h3"
      },
      "children": []
    },
    "email1_date": {
      "type": "Text",
      "props": {
        "text": "Oct 2, 2023",
        "variant": "caption"
      },
      "children": []
    },
    "email1_subject": {
      "type": "Text",
      "props": {
        "text": "Subject: Q3 Performance and Moving Forward",
        "variant": "body"
      },
      "children": []
    },
    "email1_body_paragraph1": {
      "type": "Text",
      "props": {
        "text": "Team, I want to take a moment to acknowledge the difficulty of the past quarter. Despite our best efforts, external supply chain disruptions led to a 15% miss on our sales targets. I know how hard each of you worked to navigate these hurdles, and your dedication has not gone unnoticed. We have faced headwinds before, and it is your resilience that defines Solaris Tech. Let's take this week to recalibrate and prepare for the opportunities ahead.",
        "variant": "body"
      },
      "children": []
    },
    "email1_signature": {
      "type": "Text",
      "props": {
        "text": "[Regional Manager Name]",
        "variant": "caption"
      },
      "children": []
    },
    "email2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email2_content_stack"
      ]
    },
    "email2_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email2_title",
        "email2_date",
        "email2_subject",
        "email2_body_paragraph1",
        "email2_signature"
      ]
    },
    "email2_title": {
      "type": "Text",
      "props": {
        "text": "The Q4 Sprint Strategy",
        "variant": "h3"
      },
      "children": []
    },
    "email2_date": {
      "type": "Text",
      "props": {
        "text": "Nov 1, 2023",
        "variant": "caption"
      },
      "children": []
    },
    "email2_subject": {
      "type": "Text",
      "props": {
        "text": "Subject: Launching the Q4 Sprint",
        "variant": "body"
      },
      "children": []
    },
    "email2_body_paragraph1": {
      "type": "Text",
      "props": {
        "text": "As we enter November, we are shifting our focus to the 'Q4 Sprint.' Our primary objective is client retention and strategic upselling within our existing accounts. Data shows that our current partners are looking for more integrated solutions, and we are perfectly positioned to provide that value. By deepening these relationships, we can close the gap and finish the year strong. Let's focus on quality touchpoints and demonstrating our long-term value.",
        "variant": "body"
      },
      "children": []
    },
    "email2_signature": {
      "type": "Text",
      "props": {
        "text": "[Regional Manager Name]",
        "variant": "caption"
      },
      "children": []
    },
    "email3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "email3_content_stack"
      ]
    },
    "email3_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "email3_title",
        "email3_date",
        "email3_subject",
        "email3_body_paragraph1",
        "email3_signature"
      ]
    },
    "email3_title": {
      "type": "Text",
      "props": {
        "text": "Final Month Call to Action",
        "variant": "h3"
      },
      "children": []
    },
    "email3_date": {
      "type": "Text",
      "props": {
        "text": "Dec 1, 2023",
        "variant": "caption"
      },
      "children": []
    },
    "email3_subject": {
      "type": "Text",
      "props": {
        "text": "Subject: The Final Push: Decisive Action",
        "variant": "body"
      },
      "children": []
    },
    "email3_body_paragraph1": {
      "type": "Text",
      "props": {
        "text": "This is it—the final month of 2023. We have the momentum, and the finish line is in sight. Our Q4 Sprint is yielding results, and I am calling on every member of the sales team for one final push. Every call, every demo, and every closed deal counts. Let’s show the industry what Solaris Tech is made of. We have the data, we have the resilience, and we have the best team in the business. Let’s make this December one for the record books!",
        "variant": "body"
      },
      "children": []
    },
    "email3_signature": {
      "type": "Text",
      "props": {
        "text": "[Regional Manager Name]",
        "variant": "caption"
      },
      "children": []
    },
    "quick_actions_header": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "start",
        "wrap": "wrap"
      },
      "children": [
        "q4_strategy_button",
        "sales_leaderboard_button"
      ]
    },
    "q4_strategy_button": {
      "type": "Button",
      "props": {
        "label": "Q4 Strategy Hub"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://solaris-tech.internal/q4-sprint"
          }
        }
      },
      "children": []
    },
    "sales_leaderboard_button": {
      "type": "Button",
      "props": {
        "label": "Sales Leaderboard"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://solaris-tech.internal/leaderboard"
          }
        }
      },
      "children": []
    }
  }
}
